const Redis = require('ioredis');
const redis = new Redis();

const rateLimiterScript = redis.prepare(
  'local key = KEYS[1] \n' +
  'local limit = tonumber(ARGV[1]) \n' +
  'local window = tonumber(ARGV[2]) \n' +
  'local current = redis.call('INCR', key) \n' +
  'if current == 1 then \n' +
  '  redis.call('EXPIRE', key, window) \n' +
  'end \n' +
  'if current > limit then \n' +
  '  return 0 \n' +
  'end \n' +
  'return 1'
);

async function allowRequest(userId, limit = 100, windowSeconds = 60) {
  const key = `rate-limit:${userId}`;
  // Atomic: increment and check in one script
  const allowed = await rateLimiterScript(
    key,
    [key, String(limit), String(windowSeconds)]
  );
  return allowed === 1;
}

const ok = await allowRequest('user-123');
console.log('Request allowed:', ok);

using StackExchange.Redis;

var mux = ConnectionMultiplexer.Connect("localhost:6379");
var db = mux.GetDatabase();

// Load script once
LuaScript rateLimiter = LuaScript.Prepare(
    @"local current = redis.call('INCR', KEYS[1])
      if current == 1 then
        redis.call('EXPIRE', KEYS[1], tonumber(ARGV[2]))
      end
      if current > tonumber(ARGV[1]) then
        return 0
      end
      return 1"
);

var loaded = db.LoadLuaScript(rateLimiter);

// Reuse the loaded script
bool allowed = await loaded.EvaluateAsync(
    RedisKey.E,
    new RedisKey[] { $"rate-limit:user-123" },
    new RedisValue[] { 100, 60 }
) == 1;

Console.WriteLine($"Request allowed: {allowed}");
